contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address newOwner) public {
        // ensure the new owner is genuinely different from the caller,
        // so the second call cannot legitimately succeed
        require(newOwner != address(this));

        uint balBefore = address(c).balance;

        // transfer ownership away from the test contract
        c.setOwner(newOwner); if (__ESBMC_reverted()) return;

        // now the test contract is no longer the owner: any setOwner attempt must revert
        bool reverted;
        c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && c.owner() == newOwner && address(c).balance == balBefore);
    }

    receive() external payable {}
}

